//! libint (ferric) one-electron reference matrices, stored as JSON so a GPU
//! host can check cuEST without building libint.
//!
//! Generated by `cargo run -p ferric-integrals --example gen_cuest_oe_reference`
//! into `testdata/reference/cuest/*.json`.

use ferric_core::basis::BasisSet;
use ferric_core::mol::{Atom, Molecule};
use ndarray::Array2;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RefAtom {
    pub symbol: String,
    pub z: i32,
    /// Bohr.
    pub xyz: [f64; 3],
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OneElectronReference {
    pub system: String,
    pub basis: String,
    pub generator: String,
    pub atoms: Vec<RefAtom>,
    /// Angular momentum of every shell in ferric shell order (layout guard).
    pub shell_l: Vec<i32>,
    pub nao: usize,
    /// Row-major nao × nao.
    pub s: Vec<f64>,
    pub t: Vec<f64>,
    /// Nuclear attraction (negative-definite; libint's sign).
    pub v: Vec<f64>,
}

impl OneElectronReference {
    pub fn load(path: &Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))?;
        serde_json::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))
    }

    pub fn molecule(&self) -> Molecule {
        let atoms = self
            .atoms
            .iter()
            .map(|a| Atom {
                symbol: a.symbol.clone(),
                z: a.z,
                x: a.xyz[0],
                y: a.xyz[1],
                zpos: a.xyz[2],
                ghost: false,
                n_core_ecp: 0,
            })
            .collect();
        Molecule {
            atoms,
            charge: 0,
            multiplicity: 1,
        }
    }

    pub fn basis_set(&self) -> Result<BasisSet, String> {
        ferric_core::basis::bundled(&self.basis).map_err(|e| e.to_string())
    }

    fn mat(&self, v: &[f64]) -> Array2<f64> {
        Array2::from_shape_vec((self.nao, self.nao), v.to_vec()).expect("reference matrix size")
    }

    pub fn s_matrix(&self) -> Array2<f64> {
        self.mat(&self.s)
    }
    pub fn t_matrix(&self) -> Array2<f64> {
        self.mat(&self.t)
    }
    pub fn v_matrix(&self) -> Array2<f64> {
        self.mat(&self.v)
    }
}

/// `testdata/reference/cuest` in the workspace.
pub fn reference_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/reference/cuest")
}

/// The references the GPU check is advertised to cover (NH3 in a generic
/// orientation, four bases). [`all_references`] errors if any is missing.
pub const EXPECTED_REFERENCES: [&str; 4] = [
    "nh3_generic_6-31gstar.json",
    "nh3_generic_cc-pvdz.json",
    "nh3_generic_cc-pvtz.json",
    "nh3_generic_sto-3g.json",
];

/// Every stored reference, sorted by file name. Errors, rather than returning
/// fewer, if the directory or an entry cannot be read, a file does not parse,
/// or one of [`EXPECTED_REFERENCES`] is absent, so a check over the result
/// cannot pass vacuously.
pub fn all_references() -> Result<Vec<(PathBuf, OneElectronReference)>, String> {
    let dir = reference_dir();
    let mut paths = Vec::new();
    for entry in std::fs::read_dir(&dir).map_err(|e| format!("{}: {e}", dir.display()))? {
        let path = entry.map_err(|e| format!("{}: {e}", dir.display()))?.path();
        if path.extension().is_some_and(|e| e == "json") {
            paths.push(path);
        }
    }
    paths.sort();
    let missing: Vec<&str> = EXPECTED_REFERENCES
        .iter()
        .copied()
        .filter(|name| {
            !paths
                .iter()
                .any(|p| p.file_name().is_some_and(|f| f == *name))
        })
        .collect();
    if !missing.is_empty() {
        return Err(format!(
            "{}: missing reference(s) {missing:?}; regenerate with \
             `cargo run -p ferric-integrals --example gen_cuest_oe_reference`",
            dir.display()
        ));
    }
    paths
        .into_iter()
        .map(|p| OneElectronReference::load(&p).map(|r| (p, r)))
        .collect()
}
